//! Deterministic, graph-owned release roster decisions.
//!
//! It records the exact package/version authority that later intent construction consumes, without
//! exposing a mutation route.

use callisto_model::{
    BumpReason, CommandRunner, CommitSha, Ecosystem, Package, ReleaseDecisionEntry, ReleaseDecisionV1,
    ReleaseInclusionReason, ReleasePackageId, Version,
};

use crate::error::{
    CommandFailure, CommitVerificationFailure, ReleasePreconditionRequirement, ReleaseSelectionInvalidReason,
    UnsupportedReleaseFeature,
};
use crate::{DependencyResolver, GraphError, VersionPlan, Workspace};

/// Computes one [`ReleasePackageId`] per canonical manifest, ecosystem-qualified
/// against `package`'s name.
///
/// This is the single derivation of release package identity shared by every
/// site that computes or verifies release authority: [`derive_release_decision`],
/// [`derive_release_commit_decision`], and `release::derive_release_inputs`.
/// Per this module's own established lesson (see the doc comment on
/// [`derive_release_commit_decision`]), independently reimplementing this
/// mapping at each call site is exactly the kind of duplicated derivation
/// that drifts -- so it lives here once instead.
pub(crate) fn release_package_ids(
    identity: &crate::IdentityIndex,
    package: &Package,
) -> Result<Vec<ReleasePackageId>, GraphError> {
    package
        .canonical_manifests()
        .map(|manifest| {
            let ecosystem = manifest.ecosystem();
            // A dual-manifest package's manifests may declare different names.
            let name = identity
                .native_name(&package.id, ecosystem)
                .unwrap_or(package.id.name());
            ReleasePackageId::new(ecosystem, name)
        })
        .collect::<Result<Vec<_>, _>>()
        .map_err(GraphError::from)
}

/// Derives the durable roster from a freshly computed version plan.
///
/// The caller supplies the plan from the same workspace observation; this
/// function never inspects a caller-provided release roster.
pub fn derive_release_decision<R: callisto_model::CommandRunner, D: DependencyResolver>(
    workspace: &Workspace<'_, R, D>,
    plan: &VersionPlan,
) -> Result<ReleaseDecisionV1, GraphError> {
    let mut package_ids = std::collections::BTreeMap::new();
    for package in workspace.graph.packages() {
        let ids = release_package_ids(&workspace.identity, package)?;
        package_ids.insert(package.id.clone(), ids);
    }

    let mut entries = Vec::new();
    for bump in &plan.bumps {
        // `plan` is contractually derived from this same workspace
        // observation (see doc comment above), so every bump's package must
        // already be a key here -- a miss means the plan/workspace pairing
        // itself is inconsistent, not a recoverable operator condition.
        let ids = package_ids
            .get(&bump.package)
            .ok_or_else(|| GraphError::ReleaseInvariant {
                detail: format!(
                    "version plan references package `{}`, which is absent from this workspace observation",
                    bump.package.display_name()
                ),
            })?;
        for id in ids {
            entries.push(ReleaseDecisionEntry {
                package: id.clone(),
                target_version: bump.to.clone(),
                reasons: vec![reason_from_bump(bump.reason.as_ref(), &package_ids)?],
            });
        }
    }
    ReleaseDecisionV1::new(entries).map_err(GraphError::from)
}

/// Derives a durable decision for explicit, exact release identities.
///
/// A linked group is one release unit: selecting any member includes every
/// member of that linked group which the version plan selected. All other
/// packages remain outside the authority boundary. The caller must pass
/// ecosystem-qualified [`ReleasePackageId`] values; this function never uses
/// `PackageId::matches`, whose bare-name wildcard semantics are unsuitable
/// for release authority.
pub fn derive_selected_release_decision<R: callisto_model::CommandRunner, D: DependencyResolver>(
    workspace: &Workspace<'_, R, D>,
    plan: &VersionPlan,
    selections: &[ReleasePackageId],
) -> Result<ReleaseDecisionV1, GraphError> {
    let complete = derive_release_decision(workspace, plan)?;

    let mut seen = std::collections::BTreeSet::new();
    if let Some(duplicate) = selections.iter().find(|selection| !seen.insert(*selection)) {
        return Err(GraphError::ReleaseSelectionInvalid {
            package: duplicate.clone(),
            reason: ReleaseSelectionInvalidReason::Duplicate,
        });
    }

    let selected = selections.iter().collect::<std::collections::BTreeSet<_>>();
    for selection in &selected {
        let Some(package) = workspace_package(workspace, selection) else {
            return Err(GraphError::UnknownPackage {
                id: callisto_model::PackageId::Prefixed {
                    ecosystem: selection.ecosystem(),
                    name: selection.name().to_string(),
                },
            });
        };
        let reason = if !complete.entries.iter().any(|entry| &entry.package == *selection) {
            ReleaseSelectionInvalidReason::NotARelease
        } else if package
            .publish_to
            .iter()
            .all(|target| matches!(target, callisto_model::PublishTarget::None))
        {
            ReleaseSelectionInvalidReason::NoDispatchableTarget
        } else {
            continue;
        };
        return Err(GraphError::ReleaseSelectionInvalid {
            package: (*selection).clone(),
            reason,
        });
    }

    let entries = expand_selection(workspace, complete.entries, &selected);
    ReleaseDecisionV1::new(entries).map_err(GraphError::from)
}

/// Keeps the selected entries plus every entry sharing a fixed or linked group
/// with a selection. Both release routes narrow `--package` through this.
fn expand_selection<R: callisto_model::CommandRunner, D: DependencyResolver>(
    workspace: &Workspace<'_, R, D>,
    entries: Vec<ReleaseDecisionEntry>,
    selected: &std::collections::BTreeSet<&ReleasePackageId>,
) -> Vec<ReleaseDecisionEntry> {
    // A plan-derived entry carries its linked group as a reason.
    let reason_groups = entries
        .iter()
        .filter(|entry| selected.contains(&entry.package))
        .flat_map(|entry| entry.reasons.iter())
        .filter_map(|reason| match reason {
            ReleaseInclusionReason::LinkedGroup { group_id } => Some(group_id.clone()),
            _ => None,
        })
        .collect::<std::collections::BTreeSet<_>>();
    // Config membership: a selected member's own reason is often `Changeset` or `UnreleasedVersion`.
    let config_groups = selected
        .iter()
        .flat_map(|selection| release_groups_of(workspace, selection))
        .collect::<std::collections::BTreeSet<_>>();
    entries
        .into_iter()
        .filter(|entry| {
            selected.contains(&entry.package)
                || entry.reasons.iter().any(|reason| {
                    matches!(reason, ReleaseInclusionReason::LinkedGroup { group_id } if reason_groups.contains(group_id))
                })
                || release_groups_of(workspace, &entry.package)
                    .iter()
                    .any(|group| config_groups.contains(group))
        })
        .collect()
}

/// Derives the roster of every publishable package whose current version has
/// no tag in the canonical [`crate::TagIndex`], each with
/// [`ReleaseInclusionReason::UnreleasedVersion`].
///
/// A non-empty `selections` restricts the roster to exactly those identities,
/// each of which must be unreleased and publishable. `None` means nothing is
/// unreleased.
pub fn derive_unreleased_decision<R: callisto_model::CommandRunner, D: DependencyResolver>(
    workspace: &Workspace<'_, R, D>,
    selections: &[ReleasePackageId],
) -> Result<Option<ReleaseDecisionV1>, GraphError> {
    derive_release_roster(workspace, selections, &std::collections::BTreeSet::new())
}

/// [`derive_unreleased_decision`] that also keeps the tagged releases in `resumable`: a tag
/// does not prove the rest of the release was observed.
pub(crate) fn derive_release_roster<R: callisto_model::CommandRunner, D: DependencyResolver>(
    workspace: &Workspace<'_, R, D>,
    selections: &[ReleasePackageId],
    resumable: &std::collections::BTreeSet<ReleasePackageId>,
) -> Result<Option<ReleaseDecisionV1>, GraphError> {
    let versions = workspace.base_versions()?;
    let tags = workspace.tags()?;
    let mut entries = Vec::new();
    for package in workspace.graph.packages() {
        if !has_dispatchable_target(package) {
            continue;
        }
        let version = versions.get(&package.id).ok_or_else(|| GraphError::ReleaseInvariant {
            detail: format!("package `{}` has no base version", package.id.display_name()),
        })?;
        let ids = release_package_ids(&workspace.identity, package)?;
        if version_is_tagged(tags, &package.id, version) && !ids.iter().any(|id| resumable.contains(id)) {
            continue;
        }
        for id in ids {
            entries.push(ReleaseDecisionEntry {
                package: id,
                target_version: version.clone(),
                reasons: vec![ReleaseInclusionReason::UnreleasedVersion],
            });
        }
    }

    let mut seen = std::collections::BTreeSet::new();
    for selection in selections {
        if !seen.insert(selection) {
            return Err(GraphError::ReleaseSelectionInvalid {
                package: selection.clone(),
                reason: ReleaseSelectionInvalidReason::Duplicate,
            });
        }
        let Some(package) = workspace_package(workspace, selection) else {
            return Err(GraphError::UnknownPackage {
                id: callisto_model::PackageId::Prefixed {
                    ecosystem: selection.ecosystem(),
                    name: selection.name().to_string(),
                },
            });
        };
        if !has_dispatchable_target(package) {
            return Err(GraphError::ReleaseSelectionInvalid {
                package: selection.clone(),
                reason: ReleaseSelectionInvalidReason::NoDispatchableTarget,
            });
        }
        if !entries.iter().any(|entry| &entry.package == selection) {
            return Err(GraphError::ReleaseSelectionInvalid {
                package: selection.clone(),
                reason: ReleaseSelectionInvalidReason::NotARelease,
            });
        }
    }
    if !selections.is_empty() {
        entries = expand_selection(workspace, entries, &seen);
    }
    if entries.is_empty() {
        return Ok(None);
    }
    ReleaseDecisionV1::new(entries).map(Some).map_err(GraphError::from)
}

/// Whether `version` of `package` already has a tag in the canonical [`crate::TagIndex`].
pub(crate) fn version_is_tagged(
    tags: &crate::TagIndex,
    package: &callisto_model::PackageId,
    version: &Version,
) -> bool {
    tag_of_version(tags, package, version).is_some()
}

fn tag_of_version(tags: &crate::TagIndex, package: &callisto_model::PackageId, version: &Version) -> Option<String> {
    let rendered = tags.template(package).render(version).to_string();
    if tags.contains_tag(&rendered) {
        return Some(rendered);
    }
    tags.last_tag(package)
        .filter(|tag| &tag.version == version)
        .map(|tag| tag.name.to_string())
}

/// Entries for every publishable package whose current version is tagged on `source`.
///
/// A run that created such a tag may have stopped before pushing it or finishing the release.
pub(crate) fn releases_tagged_at<R: callisto_model::CommandRunner, D: DependencyResolver>(
    workspace: &Workspace<'_, R, D>,
    source: &CommitSha,
) -> Result<Vec<ReleaseDecisionEntry>, GraphError> {
    let versions = workspace.base_versions()?;
    let tags = workspace.tags()?;
    let git = workspace.git_access();
    let mut entries = Vec::new();
    for package in workspace.graph.packages() {
        if !has_dispatchable_target(package) {
            continue;
        }
        let Some(version) = versions.get(&package.id) else {
            continue;
        };
        // Only the tag this run's tag operation would create: one made under an older template is another release's.
        let tag = tags.template(&package.id).render(version).to_string();
        if !tags.contains_tag(&tag) {
            continue;
        }
        if git.resolve_commit(&tag)?.as_ref() != Some(source) {
            continue;
        }
        for id in release_package_ids(&workspace.identity, package)? {
            entries.push(ReleaseDecisionEntry {
                package: id,
                target_version: version.clone(),
                reasons: vec![ReleaseInclusionReason::UnreleasedVersion],
            });
        }
    }
    Ok(entries)
}

pub(crate) fn has_dispatchable_target(package: &Package) -> bool {
    package
        .publish_to
        .iter()
        .any(|target| !matches!(target, callisto_model::PublishTarget::None))
}

/// The workspace package with this exact release identity.
fn workspace_package<'w, R: callisto_model::CommandRunner, D: DependencyResolver>(
    workspace: &'w Workspace<'_, R, D>,
    id: &ReleasePackageId,
) -> Option<&'w Package> {
    // By release identity, not name: a dual-manifest package's npm name can differ from its id.
    workspace
        .graph
        .packages()
        .find(|package| release_package_ids(&workspace.identity, package).is_ok_and(|ids| ids.contains(id)))
}

/// The fixed and linked groups a release package belongs to, per config.
fn release_groups_of<R: callisto_model::CommandRunner, D: DependencyResolver>(
    workspace: &Workspace<'_, R, D>,
    id: &ReleasePackageId,
) -> Vec<(&'static str, callisto_model::GroupName)> {
    let Some(package) = workspace_package(workspace, id) else {
        return Vec::new();
    };
    let groups = &workspace.config.groups;
    let fixed = groups.fixed_of.iter().map(|(member, group)| ("fixed", member, group));
    let linked = groups.linked_of.iter().map(|(member, group)| ("linked", member, group));
    // `member` keys are already canonical (`GroupTable::resolve` resolved
    // them through `IdentityIndex::resolve`), so exact equality is correct
    // here -- `PackageId::matches` would treat a Bare member key as an
    // ecosystem wildcard and could match a same-named package elsewhere.
    fixed
        .chain(linked)
        .filter(|(_, member, _)| **member == package.id)
        .map(|(kind, _, group)| (kind, group.clone()))
        .collect()
}

