fn plan(args: ReleasePlanArgs, global: &GlobalArgs) -> Result<ExitCode, CliError> {
    if global.dry_run {
        return Err(CliError::ReleasePlanDryRun);
    }
    let runner = CliCommandRunner;
    let source_global = source_global(global, args.source_root.as_deref());
    let workspace = load_workspace(&source_global, &runner)?;
    let decision = match args.from_release_commit.as_deref() {
        Some(raw) => {
            let commit = callisto_model::CommitSha::parse(raw).map_err(|error| CliError::ReleaseCommitInvalid {
                raw: raw.to_owned(),
                detail: error.to_string(),
            })?;
            let decision_path = args
                .decision
                .as_deref()
                .expect("clap requires --decision alongside --from-release-commit");
            // The workflow intentionally passes an absolute decision path
            // from its separately checked-out release source. Git's commit
            // diff and `git show REV:path` both require a repository-relative
            // path, so normalize once at the CLI boundary rather than asking
            // graph code to infer a caller's checkout layout.
            let decision_path = if decision_path.is_absolute() {
                let decision_path = dunce::canonicalize(decision_path).map_err(|source| CliError::Io {
                    source,
                    path: Some(decision_path.to_path_buf()),
                })?;
                decision_path
                    .strip_prefix(&workspace.root)
                    .map_err(|_outside_source| CliError::ReleaseDecisionOutsideSource {
                        decision: decision_path.display().to_string(),
                        root: workspace.root.display().to_string(),
                    })?
                    .to_path_buf()
            } else {
                decision_path.to_path_buf()
            };
            let decision_path = callisto_model::workspace_relative(&decision_path).map_err(|error| {
                CliError::ReleaseDecisionPathInvalid {
                    path: decision_path.display().to_string(),
                    detail: error.to_string(),
                }
            })?;
            derive_release_commit_decision(&workspace, &commit, &decision_path)?
        }
        None => {
            let selections = parse_selections(&args.packages)?;
            let inference = select_inference();
            let version_plan =
                callisto_graph::commands::plan_version(&workspace, &inference, &VersionOptions::default())?;
            derive_selected_release_decision(&workspace, &version_plan, &selections)?
        }
    };
    let locator = IgnoreWalkLocator::new(&workspace.root);
    let (intent, diagnostics) = match (
        &workspace.config.product_release,
        &args.orchestration_revision,
        &args.artifact_repository,
    ) {
        (Some(_), Some(revision), Some(repository)) => {
            let workflow_commit = callisto_model::CommitSha::parse(revision).map_err(|error| {
                CliError::ReleaseOrchestrationRevisionInvalid {
                    revision: revision.clone(),
                    detail: error.to_string(),
                }
            })?;
            let repository = callisto_model::GitHubRepository::parse(repository).map_err(|error| {
                CliError::ReleaseArtifactRepositoryInvalid {
                    repository: repository.clone(),
                    detail: error.to_string(),
                }
            })?;
            // A missing forge-repository is the graph's error; only the match lives here.
            if let Some(configured) = workspace
                .config
                .product_release
                .as_ref()
                .and_then(|release| release.forge_repository.as_ref())
                .filter(|configured| **configured != repository)
            {
                return Err(CliError::ReleaseForgeRepositoryMismatch {
                    configured: configured.as_slug(),
                    requested: repository.as_slug(),
                });
            }
            build_release_intent_with_artifacts(
                &workspace.root,
                &locator,
                &runner,
                &decision,
                ExecutionTrustProfileV1::GitCommit,
                callisto_graph::commands::ArtifactBuildPolicy {
                    repository,
                    workflow_path: callisto_model::RELEASE_COORDINATOR_WORKFLOW_PATH.to_owned(),
                    workflow_commit,
                },
            )?
        }
        (Some(_), _, _) => {
            return Err(CliError::ReleaseOrchestrationFlagsRequired);
        }
        (None, revision, repository) => {
            // The release workflow always passes both flags, including for sources predating [release].
            if revision.is_some() || repository.is_some() {
                log_line(
                    global.format,
                    "notice: --orchestration-revision and --artifact-repository ignored: the source has no [release] section; planning with zero artifact slots",
                )?;
            }
            (
                build_release_intent(
                    &workspace.root,
                    &locator,
                    &runner,
                    &decision,
                    ExecutionTrustProfileV1::GitCommit,
                )?,
                Vec::new(),
            )
        }
    };
    let permit = ApplyPermit::granted_unless_dry_run(global.dry_run)
        .expect("release plan rejects --dry-run before creating its explicit output");
    write_intent(&args.out, &intent, &permit)?;
    for diagnostic in &diagnostics {
        eprintln!("warning: {}", diagnostic.message);
    }
    match global.format {
        OutputFormat::Json => emit_report(
            &mut std::io::stdout(),
            &ReleasePlanReport {
    root: &Path,
    locator: &L,
    runner: &R,
    selections: &[ReleasePackageId],
    mode: LocalReleaseSource,
) -> Result<Option<LocalReleasePlan>, GraphError> {
    let root = canonical_root(root)?;
    let workspace = Workspace::load(root, locator, runner)?;
    plan_workspace_release(&workspace, selections, mode)
}

/// The tagged releases on HEAD whose operations are not all observed satisfied: a rerun finishes them.
///
/// A tag proves only that the tag was created. Releases tagged on an older commit are settled and
/// never observed, so only a rerun at the release commit reaches the providers.
fn incomplete_tagged_releases<R: CommandRunner, D: DependencyResolver>(
    workspace: &Workspace<'_, R, D>,
    mode: LocalReleaseSource,
) -> Result<std::collections::BTreeSet<ReleasePackageId>, GraphError> {
    let head = workspace.git_access().head_sha()?;
    let tagged: std::collections::BTreeSet<ReleasePackageId> =
        crate::commands::release_decision::releases_tagged_at(workspace, &head)?
            .into_iter()
            .map(|entry| entry.package)
            .collect();
    if tagged.is_empty() {
        return Ok(tagged);
    }
    // Without an `origin` push URL a preview cannot observe anything, so it cannot call a tagged release finished.
    if mode == LocalReleaseSource::Preview && optional_git_remote(&workspace.root, workspace.runner)?.is_none() {
        return Ok(tagged);
    }
    let profile = ExecutionTrustProfileV1::GitCommit;
    let source = match mode {
        LocalReleaseSource::Preview => SourceIdentity::GitCommit { sha: head },
        LocalReleaseSource::Trusted => observe_source(workspace, profile, ReleaseCheckout::AnyHead)?,
    };
    // The roster a run would plan with every tagged release still open, so a dependency left untagged by the
    // failed run is part of it and the dependency checks see the same packages as the real derivation.
    let Some(decision) = crate::commands::release_decision::derive_release_roster(workspace, &[], &tagged)? else {
        return Ok(Default::default());
    };
    let (_, prepared) =
        derive_release_intent_with_prepared(workspace, &decision, source, profile, None, &mut Vec::new())?;
    Ok(unsatisfied_packages(
        &workspace.root,
        workspace.runner,
        &prepared,
        &tagged,
    ))
}

/// [`plan_local_release`] over an already-loaded workspace, e.g. one built from an in-memory config.
pub fn plan_workspace_release<R: CommandRunner, D: DependencyResolver>(
    workspace: &Workspace<'_, R, D>,
    selections: &[ReleasePackageId],
    mode: LocalReleaseSource,
) -> Result<Option<LocalReleasePlan>, GraphError> {
    let resumable = incomplete_tagged_releases(workspace, mode)?;
    let Some(decision) = crate::commands::release_decision::derive_release_roster(workspace, selections, &resumable)?
    else {
        return Ok(None);
    };
    let profile = ExecutionTrustProfileV1::GitCommit;
    let source = match mode {
        LocalReleaseSource::Preview => SourceIdentity::GitCommit {
            sha: workspace.git_access().head_sha()?,
        },
        LocalReleaseSource::Trusted => observe_source(workspace, profile, ReleaseCheckout::AnyHead)?,
    };
    // A local run is its own orchestration: slots bind to the source commit.
    let artifact_policy = match (&workspace.config.product_release, &source) {
        (Some(release), SourceIdentity::GitCommit { sha }) if !release.artifacts.is_empty() => {
            release.forge_repository.clone().map(|repository| ArtifactBuildPolicy {
                repository,
                workflow_path: callisto_model::RELEASE_COORDINATOR_WORKFLOW_PATH.to_owned(),
                workflow_commit: sha.clone(),
            })
        }
        _ => None,
    };
    let remote = match mode {
        LocalReleaseSource::Preview => GitRemoteRequirement::OptionalForPreview,
        LocalReleaseSource::Trusted => GitRemoteRequirement::Required,
    };
    let mut diagnostics = Vec::new();
    let intent = derive_release_intent(
        workspace,
        &decision,
        source.clone(),
        profile,
        artifact_policy.as_ref(),
        remote,
        &mut diagnostics,
    )?;
    let tags_unbound = mode == LocalReleaseSource::Preview
        && intent
            .operations
            .iter()
            .any(|operation| operation.id().role == callisto_model::ReleaseOperationRole::Tag)
        && optional_git_remote(&workspace.root, workspace.runner)?.is_none();
    if mode == LocalReleaseSource::Trusted && observe_source(workspace, profile, ReleaseCheckout::AnyHead)? != source {
        return Err(GraphError::ReleaseIntentStale {
            reason: StaleReason::source_identity_changed(),
        });
    }
    Ok(Some(LocalReleasePlan {
        intent,
        tags_unbound,
        diagnostics,
    }))
}

