191	impl OpIndex {
192	    /// The registry publishes a package's tag waits for: those of every release identity of the package, since a
193	    /// dual Cargo and npm owner has one physical tag but a publish per manifest.
194	    fn tag_prerequisites(&self, owners: &[ReleasePackageId]) -> Vec<ReleaseOperationId> {
195	        let publishes: BTreeSet<_> = owners
196	            .iter()
197	            .flat_map(|owner| self.publishes_by_package.get(owner).into_iter().flatten().cloned())
198	            .collect();
199	        publishes.into_iter().collect()
200	    }
201	}
