203	fn derive_release_inputs_with<R: CommandRunner, D: DependencyResolver>(
204	    workspace: &Workspace<'_, R, D>,
205	    decision: &ReleaseDecisionV1,
206	    source: SourceIdentity,
207	    artifact_policy: Option<&ArtifactBuildPolicy>,
208	    remote: GitRemoteRequirement,
209	    diagnostics: &mut Vec<Diagnostic>,
210	) -> Result<DerivedReleaseInputs, GraphError> {
211	    if workspace
212	        .config
213	        .product_release
214	        .as_ref()
215	        .is_some_and(|release| release.forge_repository.is_none())
216	    {
217	        return Err(GraphError::ReleaseForgeRepositoryMissing);
218	    }
219	    let mut package_inputs = Vec::new();
220	    let Selection {
221	        selected,
222	        package_ids,
223	        owners,
224	    } = select_packages(workspace, decision)?;
225	    require_dependencies_selected(workspace, &selected, &package_ids)?;
226	    let all_packages: Vec<_> = workspace.graph.packages().map(|package| package.id.clone()).collect();
227	    let publish_edges = PublishEdgeFilter::new(
228	        &package_ids.keys().cloned().collect(),
229	        &all_packages,
230	        |id: &callisto_model::PackageId| {
231	            workspace
232	                .graph
233	                .dependencies_of(id)
234	                .map(|edge| (edge.to.clone(), edge.kind))
235	                .collect()
236	        },
237	    )?;
238	
239	    let git_remote = prepare_remote(workspace, &selected, artifact_policy, remote)?;
240	
241	    let mut ops = Ops::default();
242	    build_publish_leaves(workspace, &selected, git_remote.as_ref(), &mut package_inputs, &mut ops)?;
243	    link_publish_prerequisites(workspace, &selected, &package_ids, &publish_edges, &mut ops)?;
244	    add_tags(&selected, &package_ids, &owners, &source, &mut ops)?;
245	    add_forge_releases(workspace, &selected, &owners, &mut ops)?;
246	    let artifact_slots = add_artifact_uploads(workspace, &selected, &owners, artifact_policy, &mut ops, diagnostics)?;
247	    add_forge_publishes(&selected, &owners, &mut ops)?;
248	
249	    Ok((
250	        ReleaseInputSnapshotV1::new(source, package_inputs)?,
251	        canonical_operation_order(ops.operations)?,
252	        ops.prepared,
253	        git_remote,
254	        artifact_slots,
255	    ))
256	}
