258	fn select_packages<'w, R: CommandRunner, D: DependencyResolver>(
259	    workspace: &'w Workspace<'_, R, D>,
260	    decision: &ReleaseDecisionV1,
261	) -> Result<Selection<'w>, GraphError> {
262	    let mut selected = BTreeMap::new();
263	    let mut package_ids = BTreeMap::<callisto_model::PackageId, Vec<ReleasePackageId>>::new();
264	    let mut owners = Owners::new();
265	    for package in workspace.graph.packages() {
266	        let ids = crate::commands::release_decision::release_package_ids(&workspace.identity, package)?;
267	        if let Some(owner) = ids
268	            .iter()
269	            .find(|id| decision.entries.iter().any(|entry| &entry.package == *id))
270	        {
271	            owners.insert(package.id.clone(), owner.clone());
272	        }
273	        // One canonical manifest per ecosystem is the expected shape, but
274	        // dedup defensively -- `release_package_ids` maps every canonical
275	        // manifest, and two manifests sharing an ecosystem would otherwise
276	        // select/push the same identity twice.
277	        for id in ids.into_iter().collect::<BTreeSet<_>>() {
278	            if let Some(entry) = decision.entries.iter().find(|entry| entry.package == id) {
279	                selected.insert(id.clone(), (package, entry.target_version.clone()));
280	                package_ids.entry(package.id.clone()).or_default().push(id);
281	            }
282	        }
283	    }
284	    for entry in &decision.entries {
285	        let id = &entry.package;
286	        if !selected.contains_key(id) {
287	            return Err(GraphError::ReleasePackageNotSelected { package: id.clone() });
288	        }
289	    }
290	    Ok(Selection {
291	        selected,
292	        package_ids,
293	        owners,
294	    })
295	}
