505	fn add_tags(
506	    selected: &BTreeMap<ReleasePackageId, (&callisto_model::Package, Version)>,
507	    package_ids: &BTreeMap<callisto_model::PackageId, Vec<ReleasePackageId>>,
508	    owners: &Owners,
509	    source: &SourceIdentity,
510	    ops: &mut Ops,
511	) -> Result<(), GraphError> {
512	    let Ops {
513	        operations,
514	        prepared,
515	        index,
516	    } = ops;
517	
518	    for (id, (package, version)) in owned(selected, owners) {
519	        if !package
520	            .publish_to
521	            .iter()
522	            .any(|target| !matches!(target, PublishTarget::None))
523	        {
524	            continue;
525	        }
526	        let tag = ReleaseOperation::tag(
527	            id.clone(),
528	            version.clone(),
529	            index.tag_prerequisites(
530	                package_ids
531	                    .get(&package.id)
532	                    .map_or(std::slice::from_ref(id), Vec::as_slice),
533	            ),
534	        )?;
535	        let tag_name = package
536	            .tag_template
537	            .clone()
538	            .unwrap_or_else(|| callisto_model::TagTemplate::default_for(&package.id))
539	            .render(version);
540	        let target = match source {
541	            SourceIdentity::GitCommit { sha } => sha.clone(),
542	            SourceIdentity::HermeticContent { .. } => {
543	                return Err(GraphError::UnsupportedRelease {
544	                    feature: UnsupportedReleaseFeature::SourceIdentity,
545	                })
546	            }
547	        };
548	        prepared.insert(
549	            tag.id().clone(),
550	            PreparedOperation::Tag(TagOperation {
551	                annotation: format!("Release {tag_name}"),
552	                name: tag_name,
553	                target,
554	            }),
555	        );
556	        index.tag_by_package.insert(id.clone(), tag.id().clone());
557	        operations.insert(tag.id().clone(), tag);
558	    }
559	    Ok(())
560	}
