562	fn add_forge_releases<R: CommandRunner, D: DependencyResolver>(
563	    workspace: &Workspace<'_, R, D>,
564	    selected: &BTreeMap<ReleasePackageId, (&callisto_model::Package, Version)>,
565	    owners: &Owners,
566	    ops: &mut Ops,
567	) -> Result<(), GraphError> {
568	    let Ops {
569	        operations,
570	        prepared,
571	        index: OpIndex {
572	            tag_by_package,
573	            forge_by_package,
574	            ..
575	        },
576	        ..
577	    } = ops;
578	
579	    for (id, (package, version)) in owned(selected, owners) {
580	        if package
581	            .publish_to
582	            .iter()
583	            .any(|target| matches!(target, PublishTarget::GitHubRelease))
584	        {
585	            let tag = tag_by_package.get(id).expect("release point has tag").clone();
586	            let operation = ReleaseOperation::forge_release(id.clone(), version.clone(), vec![tag])?;
587	            let tag = match prepared.get(operation.prerequisites().first().expect("forge release has tag")) {
588	                Some(PreparedOperation::Tag(prepared_tag)) => prepared_tag.name.clone(),
589	                _ => {
590	                    return Err(GraphError::ReleaseInvariant {
591	                        detail: format!(
592	                            "forge release `{:?}` prerequisite is not a prepared Tag operation",
593	                            operation.id()
594	                        ),
595	                    })
596	                }
597	            };
598	            prepared.insert(
599	                operation.id().clone(),
600	                PreparedOperation::ForgeRelease(ForgeReleaseOperation {
601	                    tag,
602	                    prerelease: version.is_prerelease(),
603	                    notes: release_notes(&workspace.root, package.changelog.as_deref(), version)?,
604	                }),
605	            );
606	            forge_by_package.insert(id.clone(), operation.id().clone());
607	            operations.insert(operation.id().clone(), operation);
608	        }
609	    }
610	    Ok(())
611	}
