613	/// The artifact slots and their upload operations, with the uploads each product package's forge publish waits on.
614	fn add_artifact_uploads<R: CommandRunner, D: DependencyResolver>(
615	    workspace: &Workspace<'_, R, D>,
616	    selected: &BTreeMap<ReleasePackageId, (&callisto_model::Package, Version)>,
617	    owners: &Owners,
618	    artifact_policy: Option<&ArtifactBuildPolicy>,
619	    ops: &mut Ops,
620	    diagnostics: &mut Vec<Diagnostic>,
621	) -> Result<Vec<ArtifactSlotId>, GraphError> {
622	    let Ops {
623	        operations,
624	        prepared,
625	        index: OpIndex {
626	            forge_by_package,
627	            uploads_by_package,
628	            ..
629	        },
630	    } = ops;
631	
632	    let mut artifact_slots = Vec::new();
633	    if let (Some(product), Some(policy)) = (&workspace.config.product_release, artifact_policy) {
634	        require_product_package_publishes_to_forge(workspace, &product.package)?;
635	        // Resolved through IdentityIndex, not `PackageId::matches`: a Bare
636	        // package id is not an ecosystem wildcard here -- a same-name
637	        // package in another ecosystem must never match the product/artifact selector.
638	        let matches_product =
639	            |package: &callisto_model::Package| workspace.identity.identifies(&product.package, &package.id);
640	        if !selected.values().any(|(package, _)| matches_product(package)) {
641	            // The product isn't in this release, so warn instead of leaving the artifact owner's asset unregistered.
642	            for artifact in &product.artifacts {
643	                if let Some((owner_id, _)) = owned(selected, owners)
644	                    .find(|(_, (pkg, _))| workspace.identity.identifies(&artifact.package, &pkg.id))
645	                {
646	                    diagnostics.push(unreleased_product_artifact_diagnostic(
647	                        &product.package,
648	                        artifact,
649	                        owner_id,
650	                    ));
651	                }
652	            }
653	        }
654	        for (id, (package, _)) in owned(selected, owners) {
655	            if !matches_product(package) {
656	                continue;
657	            }
658	            let forge = forge_by_package.get(id).ok_or_else(|| GraphError::ReleaseInvariant {
659	                detail: format!("product package `{id}` has no forge release operation"),
660	            })?;
661	            let (tag, prerelease) = match prepared.get(forge) {
662	                Some(PreparedOperation::ForgeRelease(prepared_forge)) => {
663	                    (prepared_forge.tag.clone(), prepared_forge.prerelease)
664	                }
665	                _ => {
666	                    return Err(GraphError::ReleaseInvariant {
667	                        detail: format!("product forge release `{forge:?}` is not prepared"),
668	                    })
669	                }
670	            };
671	            for artifact in &product.artifacts {
672	                // The slot names the package whose build produced the bytes, which
673	                // need not be the product -- a plugin can ship on the product's
674	                // release. Every slot still attaches to the product's one release.
675	                let (owner_id, owner_version) = owned(selected, owners)
676	                    .find(|(_, (pkg, _))| workspace.identity.identifies(&artifact.package, &pkg.id))
677	                    .map(|(candidate, (_, owner_version))| (candidate.clone(), owner_version.clone()))
678	                    .ok_or_else(|| GraphError::ReleaseArtifactOwnerNotReleased {
679	                        asset: artifact.asset_name.clone(),
680	                        package: artifact.package.to_string(),
681	                    })?;
682	                let slot = ArtifactSlotId::new(
683	                    owner_id.clone(),
684	                    owner_version.clone(),
685	                    &artifact.target,
686	                    artifact.asset_name.clone(),
687	                    policy.repository.clone(),
688	                    policy.workflow_path.clone(),
689	                    policy.workflow_commit.clone(),
690	                )
691	                .map_err(|error| GraphError::ReleaseInvariant {
692	                    detail: format!("invalid configured artifact slot: {error}"),
693	                })?;
694	                let operation = ReleaseOperation::artifact_upload(slot.clone(), vec![forge.clone()])?;
695	                prepared.insert(
696	                    operation.id().clone(),
697	                    PreparedOperation::ArtifactUpload(ArtifactUploadOperation {
698	                        slot: slot.clone(),
699	                        tag: tag.clone(),
700	                        prerelease,
701	                    }),
702	                );
703	                // Keyed by the product's id: a plugin-built asset must still gate the product's own forge-publish.
704	                uploads_by_package
705	                    .entry(id.clone())
706	                    .or_default()
707	                    .push(operation.id().clone());
708	                operations.insert(operation.id().clone(), operation);
709	                artifact_slots.push(slot);
710	            }
711	        }
712	    }
713	    Ok(artifact_slots)
714	}
