716	fn add_forge_publishes(
717	    selected: &BTreeMap<ReleasePackageId, (&callisto_model::Package, Version)>,
718	    owners: &Owners,
719	    ops: &mut Ops,
720	) -> Result<(), GraphError> {
721	    let Ops {
722	        operations,
723	        prepared,
724	        index: OpIndex {
725	            forge_by_package,
726	            uploads_by_package,
727	            ..
728	        },
729	    } = ops;
730	
731	    // Publishing is the last forge step: a GitHub Release is only complete
732	    // once every asset it carries has been uploaded to it as a draft.
733	    for (id, (_, version)) in owned(selected, owners) {
734	        let Some(forge) = forge_by_package.get(id) else {
735	            continue;
736	        };
737	        let mut prerequisites = vec![forge.clone()];
738	        prerequisites.extend(uploads_by_package.get(id).into_iter().flatten().cloned());
739	        let operation = ReleaseOperation::forge_publish(id.clone(), version.clone(), prerequisites)?;
740	        let tag = match prepared.get(forge) {
741	            Some(PreparedOperation::ForgeRelease(prepared_forge)) => prepared_forge.tag.clone(),
742	            _ => {
743	                return Err(GraphError::ReleaseInvariant {
744	                    detail: format!("forge publish `{:?}` has no prepared draft release", operation.id()),
745	                })
746	            }
747	        };
748	        prepared.insert(
749	            operation.id().clone(),
750	            PreparedOperation::ForgePublish(ForgePublishOperation {
751	                tag,
752	                prerelease: version.is_prerelease(),
753	            }),
754	        );
755	        operations.insert(operation.id().clone(), operation);
756	    }
757	    Ok(())
758	}
