760	/// Every unreleased, publishable workspace package a selected package reaches
761	/// through a runtime, optional, or peer edge must be selected with it, or the
762	/// selected package would publish pointing at a version that does not exist.
763	/// Standalone npm platform packages are one case of this.
764	fn require_dependencies_selected<R: CommandRunner, D: DependencyResolver>(
765	    workspace: &Workspace<'_, R, D>,
766	    selected: &BTreeMap<ReleasePackageId, (&callisto_model::Package, Version)>,
767	    package_ids: &BTreeMap<callisto_model::PackageId, Vec<ReleasePackageId>>,
768	) -> Result<(), GraphError> {
769	    let mut base_versions = None;
770	    for (package, _) in selected.values() {
771	        for edge in workspace.graph.dependencies_of(&package.id) {
772	            if !matches!(edge.kind, DepKind::Runtime | DepKind::Optional | DepKind::Peer)
773	                || package_ids.contains_key(&edge.to)
774	            {
775	                continue;
776	            }
777	            let Some(dependency) = workspace
778	                .graph
779	                .packages()
780	                .find(|candidate| candidate.id == edge.to && has_dispatchable_target(candidate))
781	            else {
782	                continue;
783	            };
784	            if base_versions.is_none() {
785	                base_versions = Some(workspace.base_versions()?);
786	            }
787	            let tags = workspace.tags()?;
788	            let released = base_versions
789	                .as_ref()
790	                .and_then(|versions| versions.get(&dependency.id))
791	                .is_some_and(|current| version_is_tagged(tags, &dependency.id, current));
792	            if !released {
